/**
 * @scope/brand — Leo brand tokens + named design-system catalogs (TS surface).
 *
 * Canonical source of truth is `packages/brand/src/brand/tokens.py` and the
 * `packages/brand/src/brand/{themes,translucency,motion,typography,illustrations}/`
 * Python modules. Derived artefacts (tokens.json, tokens.ts, tokens.css,
 * vars.css) are regenerated by `python -m brand.build` and committed under
 * `src/brand/generated/`.
 *
 * Prefer CSS variables / Tailwind utilities when rendering. Import from
 * here when CSS variables are impossible (canvas / WebGL / MapLibre paint
 * props, email templates, Node.js scripts, framer-motion config).
 *
 * New here:
 *   - `translucency` — named glass recipes (`VELLUM` canonical)
 *   - `motion` — Durations / Eases / Springs / Entrances / Staggers / Scroll
 *   - `typography` — named font recipes (re-exports BRAND_FONTS today)
 *   - `illustrations` — client shim for the theme-aware pencil generator
 *
 * Read `packages/brand/DESIGN.md` for the narrative layer.
 */

export {
  BRAND,
  BRAND_COLORS,
  BRAND_RADIUS,
  BRAND_SHADOWS,
  BRAND_FONTS,
  BRAND_THEMES,
  BRAND_LOGO,
  BRAND_FAVICON_SVG,
  BRAND_FONTS_URL,
} from './src/brand/generated/tokens';

export * as translucency from './src/translucency';
export * as motion from './src/motion';
export * as typography from './src/typography';
export * as illustrations from './src/illustrations';
